import json
from pathlib import Path
P=Path(__file__).resolve().parent
c=json.loads((P/'cohort-proposal.json').read_text(encoding='utf-8'))
def dt(s):
 if s is None or s=='Present':return dict(asWritten=s,year=None,month=None,precision='unknown')
 p=s.split('-');return dict(asWritten=s,year=int(p[0]),month=int(p[1]) if len(p)>1 else None,precision='month' if len(p)>1 else 'year')
def save(name,slug,url,basis,rows,unknown):
 r=next(r for r in c['records'] if r['name']==name)
 d=dict(personId=r['proposedGraduateId'],name=name,profileUrl=url,identityBasis=basis,careerOwner='stage-4',checkedAt='2026-10-28',experienceAccess='read-all-visible',profileHistoryComplete=True,careerComplete=False,coverageNote='Entire accessible Experience read individually in Chrome, including predegree and concurrent roles; not a complete lifetime history.',jobs=[dict(employerAsWritten=e,titleAsWritten=t,start=dt(s),end=dt(end),isCurrent=end=='Present',sourceUrl=url,sourceType='self-reported-linkedin',checkedAt='2026-10-28',evidenceNote='Source spelling, precision and overlaps preserved. Entry presence is not proof of paid employment.') for e,t,s,end in rows],otherEmploymentMentions=[],firstJobAssessment=None,remainingUnknowns=unknown,integrationStatus='proposal-only')
 (P/(slug+'.history-proposal.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 r.update(careerOwner='stage-4',professionalReviewStatus='partial-history-saved-firstjob-held',degreeCompletionVerified=True,degreeCompletionYear=2013,degreeEvidenceSourceUrl=url,degreeEvidenceNote='Identity-matched self-reported MIT Operations Research PhD study endpoint2013; formal award period remains unknown.')
